CREATE POLICY department_boundary_care ON public.student_care_logs AS RESTRICTIVE FOR ALL TO authenticated USING (public.can_access_student_record(auth.uid(), student_profile_id, false)) WITH CHECK (public.can_access_student_record(auth.uid(), student_profile_id, true));
